	/*
	* How much the container grows, shrinks and reserves. These three are the engine's, unchanged -
	* they decide the reallocation pattern of every container in this file, so a container built here
	* costs the game the same number of allocations one built by the game would.
	*/

	template <typename SizeType>
	inline SizeType DefaultCalculateSlackShrink(SizeType NewMax, SizeType CurrentMax, uint64 BytesPerElement, bool bAllowQuantize, uint32 Alignment = 0)
	{
		SizeType Retval;

		// If the container has too much slack, shrink it to exactly fit the number of elements.
		const SizeType CurrentSlackElements = CurrentMax - NewMax;
		const uint64   CurrentSlackBytes = (CurrentMax - NewMax) * BytesPerElement;
		const bool bTooManySlackBytes = CurrentSlackBytes >= 16384;
		const bool bTooManySlackElements = 3 * NewMax < 2 * CurrentMax;
		if ((bTooManySlackBytes || bTooManySlackElements) && (CurrentSlackElements > 64 || !NewMax)) //  hard coded 64 :-(
		{
			Retval = NewMax;
			if (Retval > 0)
			{
				if (bAllowQuantize)
				{
					Retval = static_cast<SizeType>(FMemory::QuantizeSize(Retval * BytesPerElement, Alignment) / BytesPerElement);
				}
			}
		}
		else
		{
			Retval = CurrentMax;
		}

		return Retval;
	}

	template <typename SizeType>
	inline SizeType DefaultCalculateSlackGrow(SizeType NewMax, SizeType CurrentMax, uint64 BytesPerElement, bool bAllowQuantize, uint32 Alignment = 0)
	{
		constexpr uint64 FirstGrow    = 4;
		constexpr uint64 ConstantGrow = 16;

		SizeType Retval;

		uint64 Grow = FirstGrow; // this is the amount for the first alloc

		// CONTAINER_INITIAL_ALLOC_ZERO_SLACK: the first allocation gets no slack, which saves a lot of
		// memory across the number of containers the engine has and costs nothing measurable.
		if (CurrentMax)
		{
			// Allocate slack for the array proportional to its size.
			Grow = static_cast<uint64>(NewMax) + 3 * static_cast<uint64>(NewMax) / 8 + ConstantGrow;
		}
		else if (static_cast<uint64>(NewMax) > Grow)
		{
			Grow = static_cast<uint64>(NewMax);
		}

		if (bAllowQuantize)
		{
			Retval = static_cast<SizeType>(FMemory::QuantizeSize(Grow * BytesPerElement, Alignment) / BytesPerElement);
		}
		else
		{
			Retval = static_cast<SizeType>(Grow);
		}

		// NumElements and MaxElements are stored in 32 bit signed integers so we must be careful not to overflow here.
		if (NewMax > Retval)
		{
			// Parenthesised so Windows.h's max() macro cannot eat the call.
			Retval = (std::numeric_limits<SizeType>::max)();
		}

		return Retval;
	}

	template <typename SizeType>
	inline SizeType DefaultCalculateSlackReserve(SizeType NewMax, uint64 BytesPerElement, bool bAllowQuantize, uint32 Alignment = 0)
	{
		SizeType Retval = NewMax;

		if (bAllowQuantize)
		{
			Retval = static_cast<SizeType>(FMemory::QuantizeSize(static_cast<uint64>(Retval) * static_cast<uint64>(BytesPerElement), Alignment) / BytesPerElement);

			// NumElements and MaxElements are stored in 32 bit signed integers so we must be careful not to overflow here.
			if (NewMax > Retval)
			{
				// Parenthesised so Windows.h's max() macro cannot eat the call.
			Retval = (std::numeric_limits<SizeType>::max)();
			}
		}

		return Retval;
	}

