	/*
	* How many hash buckets a set of this many elements gets.
	*
	* This decides HashSize, and HashSize decides which bucket every element lands in
	* (KeyHash & (HashSize - 1)). A set the game hands us was sized by this function, and a set we
	* hand back has to be sized the same way, so the constants are the engine's.
	*/
	#define DEFAULT_NUMBER_OF_ELEMENTS_PER_HASH_BUCKET 2
	#define DEFAULT_BASE_NUMBER_OF_HASH_BUCKETS        8
	#define DEFAULT_MIN_NUMBER_OF_HASHED_ELEMENTS      4

